#include <stdio.h>

#define MAXN 200005

typedef long long ll;

ll bitA[MAXN];
ll bitB[MAXN];

void add(ll *bit, int n, int idx, ll val) {
    while (idx <= n) {
        bit[idx] += val;
        idx += idx & -idx;
    }
}

ll query(ll *bit, int idx) {
    ll res = 0;
    while (idx > 0) {
        res += bit[idx];
        idx -= idx & -idx;
    }
    return res;
}

int main(void) {
    int N, M;
    scanf("%d %d", &N, &M);

    int size = N + 2;

    for (int k = 0; k < M; k++) {
        int type;
        scanf("%d", &type);

        if (type == 1) {
            int I, V;
            scanf("%d %d", &I, &V);

            int l = I;
            ll rr = (ll)I + V - 1;
            int r = rr < N ? (int)rr : N;

            ll a = -1;
            ll b = (ll)V + I;

            add(bitA, size, l, a);
            add(bitA, size, r + 1, -a);

            add(bitB, size, l, b);
            add(bitB, size, r + 1, -b);
        } else if (type == 2) {
            int I, V;
            scanf("%d %d", &I, &V);

            int l = I - V + 1;
            if (l < 1) l = 1;
            int r = I;

            ll a = 1;
            ll b = (ll)V - I;

            add(bitA, size, l, a);
            add(bitA, size, r + 1, -a);

            add(bitB, size, l, b);
            add(bitB, size, r + 1, -b);
        } else {
            int I;
            scanf("%d", &I);

            ll A = query(bitA, I);
            ll B = query(bitB, I);
            ll ans = A * I + B;

            printf("%lld\n", ans);
        }
    }

    return 0;
}
