#define MAXN 200005

int N, M;
long long bitC[MAXN];
long long bitD[MAXN];

void add(long long bit[], int idx, long long val) {
    for (; idx <= N; idx += idx & -idx) {
        bit[idx] += val;
    }
}

void range_add(long long bit[], int l, int r, long long val) {
    add(bit, l, val);
    if (r + 1 <= N) {
        add(bit, r + 1, -val);
    }
}

long long query(long long bit[], int idx) {
    long long sum = 0;
    for (; idx > 0; idx -= idx & -idx) {
        sum += bit[idx];
    }
    return sum;
}

int main() {
    scanf("%d %d", &N, &M);

    while (M--) {
        int type;
        scanf("%d", &type);

        if (type == 3) {
            int i;
            scanf("%d", &i);

            long long c = query(bitC, i);
            long long d = query(bitD, i);
            printf("%lld\n", c * i + d);
        } else {
            int i;
            long long V;
            scanf("%d %lld", &i, &V);

            if (type == 1) {
                int r = i + (int)V - 1;
                if (r > N) r = N;

                range_add(bitC, i, r, -1);
                range_add(bitD, i, r, V + i);
            } else {
                int l = i - (int)V + 1;
                if (l < 1) l = 1;

                range_add(bitC, l, i, 1);
                range_add(bitD, l, i, V - i);
            }
        }
    }

    return 0;
}
